    # Also need to know if upstream not merged

    # Prepare remaining and to_delete structures
    remaining_local=[] # list of (short, reason_string, star)
    remaining_remote=[]
    skipped = {}  # star number -> message
    star_counter=1
    star_map={}  # message -> star number

    def get_star_for_message(msg):
        nonlocal star_counter
        if msg not in star_map:
            star_map[msg]=star_counter
            star_counter+=1
        return star_map[msg]

    to_delete_merged_local=[] # list of dicts {short, refname, obj, non_tracking bool}
    to_delete_merged_remote=[] # list of {remote, refname, short, non_upstream bool}
    to_delete_stray=[]
    to_delete_diverged_remote=[]

    # For HEAD detach handling
    head_to_delete = None # short name of current branch if it is to be deleted and detach allowed

    # Process local branches
    for lb in local_branches:
        short=lb["short"]
        refname=lb["refname"]
        upstream_short=lb["upstream_short"]
        upstream_ref=lb["upstream"]
        obj=lb["obj"]
        is_base = short in base_local_set
        is_tracking = upstream_short != ""
        is_upstream_gone = False
        if is_tracking:
            if upstream_short not in remote_short_to_ref:
                is_upstream_gone=True

        is_prot_pat = is_protected(short, protected_patterns) if protected_patterns else None
        # Also for tracking, should we check protected against upstream? We already decided not, based on tests that origin/* does NOT protect local.
        # But for pattern "*/*" protecting feat, our protected_match already handles that via stripping leading "*/", so "feat" vs "*/*" returns True via stripping, so it protects.
        # So we only check short.

        is_current = (short == current_branch) and current_branch != "HEAD"

        # Determine if merged
        merged = False
        if not is_upstream_gone:
            merged = is_branch_merged(refname, is_remote=False)

        # Determine diverged
        diverged = False
        diverged_with_ref = None
        if is_tracking and not is_upstream_gone:
            # If obj != upstream obj, consider diverged
            ups_obj = remote_short_to_obj.get(upstream_short)
            if ups_obj and ups_obj != obj:
                diverged = True
                diverged_with_ref = upstream_ref if upstream_ref else f"refs/remotes/{upstream_short}"

        # Determine stray
        stray = is_upstream_gone

        # Determine tracking base
        is_tracks_base = False
        tracks_base_name = None
        if short in base_local_set:
            pass
        else:
            # Check if upstream is in base_remote_shorts
            if upstream_short in base_remote_shorts:
                is_tracks_base=True
                tracks_base_name=upstream_short

        # Decision for remaining vs deletion
        # First check base protection
        if is_base:
