                else:
                    remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot_pat}`]", None))
            elif stray:
                # What message for stray protected? Not observed, but likely similar?
                remaining_local.append((short, f"[stray, but: protected by a pattern `{is_prot_pat}`]", None))
            elif diverged:
