    # Try stripping leading "*/" and "**/" repeatedly
    pats=[pattern]
    p=pattern
    while True:
        if p.startswith("*/"):
            p=p[2:]
            pats.append(p)
        elif p.startswith("**/"):
            p=p[3:]
            pats.append(p)
        else:
            break
    for pat in pats:
        try:
            if fnmatch.fnmatch(branch_short, pat):
                return True
        except:
            pass
    return False

