            if merged:
                if not is_tracking:
                    remaining_local.append((short, f"[merged non-tracking, but: protected by a pattern `{is_prot}`]", None))
                else:
                    remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
            elif stray:
                remaining_local.append((short, f"[stray, but: protected by a pattern `{is_prot}`]", None))
            elif diverged:
                remaining_local.append((short, f"[diverged with {diverged_with}, but: protected by a pattern `{is_prot}`]", None))
            else:
                remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
            continue

        if is_current and no_detach:
            would=False
            if stray and allow_stray:
                would=True
            elif diverged and merged:
                rn=up_short.split("/")[0] if up_short else ""
                if rn in allow_diverged:
                    would=True
            elif merged:
                if is_tracking and allow_merged_local:
                    would=True
                elif not is_tracking and allow_local:
                    would=True
            if would:
                if merged:
                    remaining_local.append((short, "[merged, but: HEAD]", None))
                elif stray:
                    remaining_local.append((short, "[stray, but: HEAD]", None))
                else:
                    remaining_local.append((short, f"[diverged with {diverged_with}, but: HEAD]", None))
                continue

        if stray:
            if allow_stray:
                if is_current and no_detach:
                    pass
                else:
                    to_delete_stray.append(lb)
                    if is_current:
                        head_to_delete=short
                    continue
            else:
                remaining_local.append((short, "[stray, but: delete range `stray` was not given]", None))
                continue
        if diverged and merged:
            if up_short:
                rn=up_short.split("/")[0]
                if rn in allow_diverged:
                    to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":False,"diverged":True,"up_short":up_short,"up_ref":up_ref,"subject":lb.get("subject","")})
                    if is_current:
                        head_to_delete=short
                    continue
            rn=up_short.split("/")[0] if up_short else "origin"
            remaining_local.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{rn}` was not given]", None))
            continue
        if merged:
            if is_tracking:
                if allow_merged_local:
                    to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":False,"diverged":False,"subject":lb.get("subject","")})
                    if is_current:
                        head_to_delete=short
                    continue
                else:
                    remaining_local.append((short, "[merged, but: delete range `merged-local` was not given]", None))
                    continue
            else:
                if allow_local:
                    to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":True,"diverged":False,"subject":lb.get("subject","")})
                    if is_current:
                        head_to_delete=short
                    continue
                else:
                    msg="Set an upstream to make it a tracking branch or add `--delete 'local'` flag."
                    star=get_star(msg)
                    remaining_local.append((short, f"*{star}", star))
                    skipped[star]=msg
                    continue
        if diverged:
            rn=up_short.split("/")[0] if up_short else "origin"
            remaining_local.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{rn}` was not given]", None))
            continue
        remaining_local.append((short, "", None))

    # remote
    for rb in remote_branches:
        short=rb["short"]
        refname=rb["refname"]
        obj=rb["obj"]
        is_base = short in base_remote_shorts
        is_upstream = short in upstream_remote_shorts
        is_prot = is_protected(short, protected_patterns) if protected_patterns else None
        merged = is_branch_merged(refname, is_remote=True)
