                else:
                    remaining_remote.append((short, f"[merged, but: delete range `merged-remote:{remote_name}` was not given]", None))
                    continue
            else:
                if remote_name in allow_remote:
                    to_delete_merged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"obj":obj,"non_upstream":True})
                    continue
                else:
                    # check if merged-remote would also delete? Actually non-upstream categorized as remote, not merged-remote? But original allows remote:origin to delete non-upstream merged remote. Also merged:origin includes merged-remote:origin, so if allow_merged_remote contains remote, should it also delete non-upstream? In original, with -d merged:origin, non-upstream remote was NOT deleted, it was skipped with *3, not deleted. So merged-remote does NOT delete non-upstream. So we must not delete non-upstream via merged-remote, only via remote.
                    # So for non-upstream, check allow_remote, not allow_merged_remote
                    # Actually we already checked allow_remote above, but we also had earlier check for allow_merged_remote for upstream only. For non-upstream, we check allow_remote.
                    # If not allowed, show *3
                    msg=f"Make it upstream of a tracking branch or add `--delete 'remote:{remote_name}'` flag."
                    star=get_star(msg)
                    remaining_remote.append((short, f"*{star}", star))
                    skipped[star]=msg
                    continue
        if diverged:
            remote_name=short.split("/")[0]
            # Find local tracking that is merged
            found=False
            for lb in local_branches:
                if lb["upstream_short"]==short:
                    if is_branch_merged(lb["refname"], is_remote=False):
                        if remote_name in allow_diverged:
                            to_delete_diverged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"obj":obj})
                            found=True
                            break
            if found:
                continue
            remaining_remote.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{remote_name}` was not given]", None))
            continue

        remaining_remote.append((short, "", None))

    # Now remaining sorted
    remaining_local_sorted=sorted(remaining_local, key=lambda x: x[0])
    remaining_remote_sorted=sorted(remaining_remote, key=lambda x: x[0])

    # Prepare output lines for remaining
    out_lines=[]
    out_lines.append("Branches that will remain:")
    out_lines.append("  local branches:")
    for short,reason,star in remaining_local_sorted:
        if reason.startswith("*"):
            out_lines.append(f"    {short} {reason}")
        elif reason:
            out_lines.append(f"    {short} {reason}")
        else:
            out_lines.append(f"    {short}")
    out_lines.append("  remote references:")
    for short,reason,star in remaining_remote_sorted:
        if reason.startswith("*"):
            out_lines.append(f"    {short} {reason}")
        elif reason:
            out_lines.append(f"    {short} {reason}")
        else:
            out_lines.append(f"    {short}")
    if skipped:
