        for star_num in sorted(skipped.keys()):
            out_lines.append(f"    *{star_num}: {skipped[star_num]}")
    out_lines.append("")

    # Print remaining
    for line in out_lines:
        print(line)

    # Prepare deletion groups for display
    # Group headers
    # We'll create list of groups in order: merged local, merged remote, stray, diverged remote

    # To match original, we need to handle display of items before actual git calls
    # For dry-run, original does NOT ask confirm, so we go directly to display and then dry-run messages.

    # Check confirm
    has_deletions = bool(to_delete_merged_local or to_delete_merged_remote or to_delete_stray or to_delete_diverged_remote)

    if has_deletions and not dry_run and not no_confirm:
        # Need tty
        if not sys.stdin.isatty():
            sys.stderr.write("Error: IO error: not a terminal\n\nCaused by:\n    not a terminal\n")
            sys.exit(1)
        # Prompt
        sys.stdout.write("Confirm? [y/N] \x1b[?25l")
        sys.stdout.flush()
        try:
            resp = sys.stdin.readline()
        except:
            resp = ""
        resp_stripped = resp.strip().lower()
        if resp_stripped in ("y","yes"):
            sys.stdout.write("\x1b[2KConfirm? yes\n\x1b[?25h")
            sys.stdout.flush()
        else:
            sys.stdout.write("\x1b[2KConfirm? no\n\x1b[?25h\nCancelled\n")
            sys.stdout.flush()
            sys.exit(0)

    # Now print deletion groups if any
    # For merged local
    if to_delete_merged_local:
        print("Delete merged local branches:")
        for item in sorted(to_delete_merged_local, key=lambda x: x["short"]):
            short=item["short"]
            if item.get("non_tracking"):
                print(f"  - {short} (non-tracking)")
            else:
                print(f"  - {short}")

    if to_delete_merged_remote:
        print("Delete merged remote refs:")
        for item in sorted(to_delete_merged_remote, key=lambda x: x["short"]):
            remote=item["remote"]
            refname=item["refname"]
            if item.get("non_upstream"):
                print(f"  - {remote}, {refname} (non-upstream)")
            else:
                print(f"  - {remote}, {refname}")

    if to_delete_stray:
        print("Delete stray local branches:")
        for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
            print(f"  - {lb['short']}")

    if to_delete_diverged_remote:
        print("Delete diverged remote refs:")
        for item in sorted(to_delete_diverged_remote, key=lambda x: x["short"]):
            remote=item["remote"]
            refname=item["refname"]
            print(f"  - {remote}, {refname}")

    # Handle HEAD detach Note
    if head_to_delete:
        # Find info for that branch to get obj short and subject for dry-run message
        # Find local branch with that short
        info = local_short_to_info.get(head_to_delete)
        if info:
            obj_short = info["obj"][:7] if len(info["obj"])>=7 else info["obj"]
            subject = info.get("subject","")
        else:
            obj_short = ""
            subject = ""
        if dry_run:
            print(f"Note: switching to 'refs/heads/{head_to_delete}' (dry run)")
            print("You are in 'detached HED' state... blah blah...")
            print(f"HEAD is now at {obj_short} {subject} (dry run)")
        else:
            print(f"Note: switching to 'refs/heads/{head_to_delete}'.")
            # Run git checkout
            # The checkout will print detached HEAD message via git itself
            subprocess.run(["git","checkout", f"refs/heads/{head_to_delete}"], stdout=sys.stdout, stderr=sys.stderr)
            print(f"HEAD is now at {obj_short} {subject}")

    # Now handle remote deletions (push)
    # For each remote ref in merged and diverged
    all_remote_deletions = to_delete_merged_remote + to_delete_diverged_remote
    # Group by remote? Original pushes each individually
    for item in sorted(all_remote_deletions, key=lambda x: x["short"]):
        remote=item["remote"]
        refname=item["refname"]  # refs/heads/xxx
        # Run git push --delete
        if dry_run:
            subprocess.run(["git","push","--delete","--no-verify","--dry-run", remote, refname], stdout=sys.stdout, stderr=sys.stderr)
        else:
            subprocess.run(["git","push","--delete","--no-verify", remote, refname], stdout=sys.stdout, stderr=sys.stderr)

    # Local deletions
    for item in sorted(to_delete_merged_local, key=lambda x: x["short"]):
        short=item["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).")
        else:
            # git branch --delete --force
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

    for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
        short=lb["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).")
        else:
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

    # Note: diverged local already included in merged local deletions, so not separate

if __name__=="__main__":
    main()
