                diverged_with=up_ref if up_ref else f"refs/remotes/{up_short}"
        stray = is_up_gone
        is_tracks_base=False
        tracks_base_name=None
        if not is_base:
            if up_short in base_remote_shorts:
                is_tracks_base=True
                tracks_base_name=up_short

        if is_base:
            if stray:
                remaining_local.append((short, "[stray, but: base]", None))
            else:
                remaining_local.append((short, "[base]", None))
            continue
        if is_tracks_base:
            remaining_local.append((short, f"[tracks base `{tracks_base_name}`]", None))
            continue

        if is_prot:
            if merged:
                if not is_tracking:
                    remaining_local.append((short, f"[merged non-tracking, but: protected by a pattern `{is_prot}`]", None))
                else:
                    remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
            elif stray:
                remaining_local.append((short, f"[stray, but: protected by a pattern `{is_prot}`]", None))
            elif diverged:
                remaining_local.append((short, f"[diverged with {diverged_with}, but: protected by a pattern `{is_prot}`]", None))
            else:
                remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
            continue

