            refname=item["refname"]
            if item.get("non_upstream"):
                print(f"  - {remote}, {refname} (non-upstream)")
            else:
                print(f"  - {remote}, {refname}")

    if to_delete_stray:
        print("Delete stray local branches:")
        for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
            print(f"  - {lb['short']}")

    if to_delete_diverged_remote:
        print("Delete diverged remote refs:")
        for item in sorted(to_delete_diverged_remote, key=lambda x: x["short"]):
            remote=item["remote"]
            refname=item["refname"]
            print(f"  - {remote}, {refname}")

    # Handle HEAD detach Note
    if head_to_delete:
        # Find info for that branch to get obj short and subject for dry-run message
        # Find local branch with that short
        info = local_short_to_info.get(head_to_delete)
        if info:
            obj_short = info["obj"][:7] if len(info["obj"])>=7 else info["obj"]
            subject = info.get("subject","")
        else:
            obj_short = ""
            subject = ""
        if dry_run:
            print(f"Note: switching to 'refs/heads/{head_to_delete}' (dry run)")
            print("You are in 'detached HED' state... blah blah...")
            print(f"HEAD is now at {obj_short} {subject} (dry run)")
