    for item in sorted(to_delete_merged_local, key=lambda x: x["short"]):
        short=item["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).")
        else:
            # git branch --delete --force
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

    for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
        short=lb["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).")
        else:
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

    # Note: diverged local already included in merged local deletions, so not separate

if __name__=="__main__":
    main()
