            sys.stderr.write(" * `git config --global trim.bases develop,master` to set globally.\n")
            sys.stderr.write(" * `git trim --bases develop,master` to set temporarily.\n")
            sys.stderr.write("Error: No base branch is found!\n")
            sys.stderr.flush()
            sys.exit(1)
    else:
        tokens=[b.strip() for b in bases.split(",") if b.strip()!=""]
        for token in tokens:
            first=token.split("/")[0]
            is_remote=first in remotes
            if is_remote:
                ref=f"refs/remotes/{token}"
                if token in remote_short_to_ref:
                    base_remote_shorts.add(token)
                    base_remote_refs.add(remote_short_to_ref[token])
                else:
                    out_chk,_,code_chk = run_git_output(["show-ref","--verify",ref])
                    if code_chk==0:
                        base_remote_shorts.add(token)
                        base_remote_refs.add(ref)
                    else:
                        out_lchk,_,code_lchk = run_git_output(["show-ref","--verify", f"refs/heads/{token}"])
                        if code_lchk==0:
                            base_local_set.add(token)
                            info=local_short_to_info.get(token)
                            if info and info["upstream_short"]:
                                ups=info["upstream_short"]
                                if ups in remote_short_to_ref:
                                    base_remote_shorts.add(ups)
                                    base_remote_refs.add(remote_short_to_ref[ups])
            else:
                ref=f"refs/heads/{token}"
                out_lchk,_,code_lchk = run_git_output(["show-ref","--verify", ref])
                if code_lchk==0:
                    base_local_set.add(token)
                    info=local_short_to_info.get(token)
                    if info and info["upstream_short"]:
                        ups=info["upstream_short"]
                        if ups in remote_short_to_ref:
                            base_remote_shorts.add(ups)
                            base_remote_refs.add(remote_short_to_ref[ups])
                        else:
                            out_ups,_,code_ups = run_git_output(["show-ref","--verify", f"refs/remotes/{ups}"])
                            if code_ups==0:
                                base_remote_shorts.add(ups)
                                base_remote_refs.add(f"refs/remotes/{ups}")
                else:
                    out_rchk,_,code_rchk = run_git_output(["show-ref","--verify", f"refs/remotes/{token}"])
                    if code_rchk==0:
                        base_remote_shorts.add(token)
                        base_remote_refs.add(f"refs/remotes/{token}")

    if not base_remote_refs:
        for name in base_local_set:
            base_remote_refs.add(f"refs/heads/{name}")

    protected_patterns=[]
    if protected:
        protected_patterns=[p.strip() for p in protected.split(",") if p.strip()!=""]

    allow_merged_local=False
    allow_merged_remote={}
    allow_stray=False
    allow_diverged={}
    allow_local=False
    allow_remote={}
    def add_remote_scope(d,scope):
        if scope=="*":
            for r in remotes:
                d[r]=True
        else:
            d[scope]=True

    for dr in delete_ranges:
        r=dr["range"]
        sc=dr["scope"]
        if r=="merged":
            allow_merged_local=True
            add_remote_scope(allow_merged_remote, sc)
        elif r=="merged-local":
            allow_merged_local=True
        elif r=="merged-remote":
            add_remote_scope(allow_merged_remote, sc)
        elif r=="stray":
            allow_stray=True
        elif r=="diverged":
            add_remote_scope(allow_diverged, sc)
        elif r=="local":
            allow_local=True
        elif r=="remote":
            add_remote_scope(allow_remote, sc)

    # Determine if tracking scanning enabled
    tracking_enabled = allow_merged_local or len(allow_merged_remote)>0 or allow_stray or len(allow_diverged)>0
    local_enabled = allow_local
    remote_enabled = len(allow_remote)>0

    merged_local_refs=set()
    merged_remote_refs=set()
    for base_ref in base_remote_refs:
        out_ml,_,_ = run_git_output(["branch","--format=%(refname)","--merged", base_ref])
        for line in out_ml.splitlines():
            line=line.strip()
            if line:
                merged_local_refs.add(line)
        out_mr,_,_ = run_git_output(["branch","--format=%(refname)","--remote","--merged", base_ref])
        for line in out_mr.splitlines():
            line=line.strip()
            if line:
                merged_remote_refs.add(line)

    def is_merged_cherry(base_ref, branch_ref):
        out,_,_ = run_git_output(["rev-list","--cherry-pick","--right-only","--no-merges","-n1", f"{base_ref}...{branch_ref}"])
        return out==""

    def is_branch_merged(branch_ref, is_remote=False):
        if is_remote:
            if branch_ref in merged_remote_refs:
                return True
        else:
            if branch_ref in merged_local_refs:
                return True
        for base_ref in base_remote_refs:
            if is_merged_cherry(base_ref, branch_ref):
                return True
        return False

    upstream_remote_shorts=set()
    for lb in local_branches:
        if lb["upstream_short"]:
            upstream_remote_shorts.add(lb["upstream_short"])

    remaining_local=[]
    remaining_remote=[]
    skipped={}
    # fixed star numbers
    # *1 = merged:*
    # *2 = local
    # *3 = remote
    STAR_MERGED=1
    STAR_LOCAL=2
    STAR_REMOTE=3
    # messages
    MSG_MERGED="Add `--delete 'merged:*'` flag."
    MSG_LOCAL="Set an upstream to make it a tracking branch or add `--delete 'local'` flag."
    # For remote, need to produce message per remote? Original uses origin as example but for second remote uses its name
    # We'll generate message for each remote that appears as non-upstream

    to_delete_merged_local=[]
    to_delete_merged_remote=[]
    to_delete_stray=[]
    to_delete_diverged_remote=[]
    head_to_delete=None

    # Precompute for tracking disabled case
    if not tracking_enabled:
        # All tracking branches become *1 skipped, except those that are to be deleted via local/remote? Actually local non-tracking and remote non-upstream are handled separately.
        for lb in local_branches:
            short=lb["short"]
            is_tracking = lb["upstream_short"] != ""
            # For tracking or base, mark as *1
            if is_tracking or short in base_local_set:
                remaining_local.append((short, f"*{STAR_MERGED}", STAR_MERGED))
                skipped[STAR_MERGED]=MSG_MERGED
            else:
                # non-tracking
                if allow_local and is_branch_merged(lb["refname"], is_remote=False):
                    # would be deleted
                    pass
                else:
                    # remain as normal? For -d local only with only tracking, there is no non-tracking, but for -d local with localOnly, localOnly should be deleted, not skipped.
                    # So for non-tracking when tracking disabled, if local_enabled and merged, delete, else remain as normal? But original for -d local only with feat+localOnly showed tracking as *1 and localOnly deleted, so non-tracking not skipped when local_enabled.
                    # For -d local only with only feat (no non-tracking), all tracking *1, no remaining base? But original showed all *1.
                    # So we need to handle non-tracking separately after this loop. We'll not add non-tracking here, handle later.
                    pass
        # For remote tracking (upstream and base remote) also *1
        for rb in remote_branches:
            short=rb["short"]
            # If it's base or upstream, *1
            # For remote non-upstream, it should be handled as *3 if remote_enabled false, etc.
            is_upstream = short in upstream_remote_shorts
            is_base = short in base_remote_shorts
            if is_base or is_upstream:
                remaining_remote.append((short, f"*{STAR_MERGED}", STAR_MERGED))
                skipped[STAR_MERGED]=MSG_MERGED
            else:
                # non-upstream remote
                # If remote_enabled, it would be considered for deletion, else *3
                pass
        # Now handle non-tracking local and non-upstream remote for the tracking disabled case
        for lb in local_branches:
            short=lb["short"]
            is_tracking = lb["upstream_short"] != ""
            if not is_tracking:
                if allow_local and is_branch_merged(lb["refname"], is_remote=False):
                    # check protected
                    is_prot = is_protected(short, protected_patterns) if protected_patterns else None
                    if is_prot:
                        remaining_local.append((short, f"[merged non-tracking, but: protected by a pattern `{is_prot}`]", None))
                    else:
                        to_delete_merged_local.append({"short":short,"refname":lb["refname"],"obj":lb["obj"],"non_tracking":True,"subject":lb.get("subject","")})
                        if short==current_branch:
                            head_to_delete=short
                else:
                    # remain? For -d local only with only tracking, there is no non-tracking, so nothing.
                    # For -d remote only with tracking disabled and local non-tracking present, local non-tracking should be *2 skipped
                    if not allow_local:
                        # Show *2
                        remaining_local.append((short, f"*{STAR_LOCAL}", STAR_LOCAL))
                        skipped[STAR_LOCAL]=MSG_LOCAL
                    else:
                        # Not merged, remain with no reason? Let's show as is
                        remaining_local.append((short, "", None))
        for rb in remote_branches:
            short=rb["short"]
            is_upstream = short in upstream_remote_shorts
            is_base = short in base_remote_shorts
            if is_base or is_upstream:
                continue # already handled as *1
            # non-upstream
            remote_name=short.split("/")[0]
            if allow_remote and remote_name in allow_remote and is_branch_merged(rb["refname"], is_remote=True):
                is_prot = is_protected(short, protected_patterns) if protected_patterns else None
                if is_prot:
                    remaining_remote.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
                else:
                    to_delete_merged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"obj":rb["obj"],"non_upstream":True})
            else:
                # skipped *3 if remote not enabled or not merged?
                if not remote_enabled:
                    msg=f"Make it upstream of a tracking branch or add `--delete 'remote:{remote_name}'` flag."
                    # Use fixed star 3 but message includes remote name
                    remaining_remote.append((short, f"*{STAR_REMOTE}", STAR_REMOTE))
                    skipped[STAR_REMOTE]=msg
                else:
                    # remote enabled but not merged -> remain with no reason?
                    remaining_remote.append((short, "", None))
        # Now we have remaining and deletions for tracking disabled case, we can skip the normal processing below
        # But we need to also handle protected for tracking branches that are *1? In tracking disabled case, protected should still be considered? Original for -d local with protected? Let's not overcomplicate.
        # For simplicity, if tracking disabled, we have already built remaining and deletions, so we can jump to output.
        # However we need to ensure base branches that are *1 are not also shown as base.
        # Our current logic already handled tracking as *1, so we should not go into normal processing.
        # We'll set a flag to skip normal processing.
        skip_normal = True
    else:
        skip_normal=False

    if not skip_normal:
        remaining_local=[]
        remaining_remote=[]
        skipped={}
        to_delete_merged_local=[]
        to_delete_merged_remote=[]
        to_delete_stray=[]
        to_delete_diverged_remote=[]
        head_to_delete=None
        # We'll need star handling for local and remote disabled
        # For tracking enabled case, we need to handle local and remote disabled
        for lb in local_branches:
            short=lb["short"]
            refname=lb["refname"]
            up_short=lb["upstream_short"]
            up_ref=lb["upstream"]
            obj=lb["obj"]
            is_base = short in base_local_set
            is_tracking = up_short != ""
            is_up_gone = False
            if is_tracking and up_short not in remote_short_to_ref:
                is_up_gone=True
            is_prot = is_protected(short, protected_patterns) if protected_patterns else None
            is_current = (short == current_branch) and current_branch != "HEAD"
            merged=False
            if not is_up_gone:
                merged=is_branch_merged(refname, is_remote=False)
            diverged=False
            diverged_with=None
            if is_tracking and not is_up_gone:
                ups_obj=remote_short_to_obj.get(up_short)
                if ups_obj and ups_obj!=obj:
                    diverged=True
                    diverged_with=up_ref if up_ref else f"refs/remotes/{up_short}"
            stray=is_up_gone
            is_tracks_base=False
            tracks_base_name=None
            if not is_base and up_short in base_remote_shorts:
                is_tracks_base=True
                tracks_base_name=up_short

            if is_base:
                if stray:
                    remaining_local.append((short, "[stray, but: base]", None))
                else:
                    remaining_local.append((short, "[base]", None))
                continue
            if is_tracks_base:
                remaining_local.append((short, f"[tracks base `{tracks_base_name}`]", None))
                continue

            if is_prot:
                if merged:
                    if not is_tracking:
                        remaining_local.append((short, f"[merged non-tracking, but: protected by a pattern `{is_prot}`]", None))
                    else:
                        remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
                else:
                    # For stray or diverged protected, use same
                    if stray:
                        remaining_local.append((short, f"[stray, but: protected by a pattern `{is_prot}`]", None))
                    elif diverged:
                        remaining_local.append((short, f"[diverged with {diverged_with}, but: protected by a pattern `{is_prot}`]", None))
                    else:
                        remaining_local.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
                continue

            if is_current and no_detach:
                would=False
                if stray and allow_stray:
                    would=True
                elif diverged and merged:
                    rn=up_short.split("/")[0] if up_short else ""
                    if rn in allow_diverged:
                        would=True
                elif merged:
                    if is_tracking and allow_merged_local:
                        would=True
                    elif not is_tracking and allow_local:
                        would=True
                if would:
                    if merged:
                        remaining_local.append((short, "[merged, but: HEAD]", None))
                    else:
                        remaining_local.append((short, f"[{ 'stray' if stray else 'diverged with '+str(diverged_with) }, but: HEAD]", None))
                    continue

            if stray:
                if allow_stray:
                    to_delete_stray.append(lb)
                    if is_current:
                        head_to_delete=short
                    continue
                else:
                    remaining_local.append((short, "[stray, but: delete range `stray` was not given]", None))
                    continue

            if diverged and merged:
                if up_short:
                    rn=up_short.split("/")[0]
                    if rn in allow_diverged:
                        to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":False,"subject":lb.get("subject","")})
                        if is_current:
                            head_to_delete=short
                        continue
                rn=up_short.split("/")[0] if up_short else "origin"
                remaining_local.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{rn}` was not given]", None))
                continue

            if merged:
                if is_tracking:
                    if allow_merged_local:
                        to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":False,"subject":lb.get("subject","")})
                        if is_current:
                            head_to_delete=short
                        continue
                    else:
                        remaining_local.append((short, f"[merged, but: delete range `merged-local` was not given]", None))
                        continue
                else:
                    if allow_local:
                        to_delete_merged_local.append({"short":short,"refname":refname,"obj":obj,"non_tracking":True,"subject":lb.get("subject","")})
                        if is_current:
                            head_to_delete=short
                        continue
                    else:
                        # skipped *2
                        remaining_local.append((short, f"*{STAR_LOCAL}", STAR_LOCAL))
                        skipped[STAR_LOCAL]=MSG_LOCAL
                        continue
            if diverged:
                rn=up_short.split("/")[0] if up_short else "origin"
                remaining_local.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{rn}` was not given]", None))
                continue

            # Non-tracking or tracking not merged
            if not is_tracking:
                if not local_enabled:
                    remaining_local.append((short, f"*{STAR_LOCAL}", STAR_LOCAL))
                    skipped[STAR_LOCAL]=MSG_LOCAL
                else:
                    remaining_local.append((short, "", None))
            else:
                remaining_local.append((short, "", None))

        for rb in remote_branches:
            short=rb["short"]
            refname=rb["refname"]
            is_base = short in base_remote_shorts
            is_upstream = short in upstream_remote_shorts
            is_prot = is_protected(short, protected_patterns) if protected_patterns else None
            merged = is_branch_merged(refname, is_remote=True)
            diverged=False
            diverged_with=None
            for lb in local_branches:
                if lb["upstream_short"]==short and lb["obj"]!=rb["obj"]:
                    diverged=True
                    diverged_with=lb["refname"]
                    break

            if is_base:
                remaining_remote.append((short, "[base]", None))
                continue
            if is_prot:
                remaining_remote.append((short, f"[merged, but: protected by a pattern `{is_prot}`]", None))
                continue

            if merged:
                remote_name=short.split("/")[0]
                if is_upstream:
                    if remote_name in allow_merged_remote:
                        to_delete_merged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"non_upstream":False})
                        continue
                    else:
                        remaining_remote.append((short, f"[merged, but: delete range `merged-remote:{remote_name}` was not given]", None))
                        continue
                else:
                    if remote_name in allow_remote:
                        to_delete_merged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"non_upstream":True})
                        continue
                    else:
                        msg=f"Make it upstream of a tracking branch or add `--delete 'remote:{remote_name}'` flag."
                        remaining_remote.append((short, f"*{STAR_REMOTE}", STAR_REMOTE))
                        skipped[STAR_REMOTE]=msg
                        continue
            if diverged:
                remote_name=short.split("/")[0]
                for lb in local_branches:
                    if lb["upstream_short"]==short and is_branch_merged(lb["refname"], is_remote=False):
                        if remote_name in allow_diverged:
                            to_delete_diverged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short})
                            diverged=False
                            break
                if diverged:
                    remaining_remote.append((short, f"[diverged with {diverged_with}, but: delete range `diverged:{remote_name}` was not given]", None))
                    continue
                else:
                    # if we deleted, skip remaining
                    if any(d["short"]==short for d in to_delete_diverged_remote):
                        continue
            remaining_remote.append((short, "", None))

    remaining_local_sorted=sorted(remaining_local, key=lambda x: x[0])
    remaining_remote_sorted=sorted(remaining_remote, key=lambda x: x[0])

    out_lines=[]
    out_lines.append("Branches that will remain:")
    out_lines.append("  local branches:")
    for short,reason,star in remaining_local_sorted:
        if reason.startswith("*"):
            out_lines.append(f"    {short} {reason}")
        elif reason:
            out_lines.append(f"    {short} {reason}")
        else:
            out_lines.append(f"    {short}")
    out_lines.append("  remote references:")
    for short,reason,star in remaining_remote_sorted:
        if reason.startswith("*"):
            out_lines.append(f"    {short} {reason}")
        elif reason:
            out_lines.append(f"    {short} {reason}")
        else:
            out_lines.append(f"    {short}")
    if skipped:
        out_lines.append("  Some branches are skipped. Consider following to scan them:")
        for star_num in sorted(skipped.keys()):
            out_lines.append(f"    *{star_num}: {skipped[star_num]}")
    out_lines.append("")

    for line in out_lines:
        print(line, flush=True)

    has_del = bool(to_delete_merged_local or to_delete_merged_remote or to_delete_stray or to_delete_diverged_remote)

    if has_del and not dry_run and not no_confirm:
        if not sys.stdin.isatty():
            sys.stderr.write("Error: IO error: not a terminal\n\nCaused by:\n    not a terminal\n")
            sys.stderr.flush()
            sys.exit(1)
        sys.stdout.write("Confirm? [y/N] \x1b[?25l")
        sys.stdout.flush()
        resp=sys.stdin.readline()
        if resp.strip().lower() in ("y","yes"):
            sys.stdout.write("\x1b[2KConfirm? yes\n\x1b[?25h")
            sys.stdout.flush()
        else:
            sys.stdout.write("\x1b[2KConfirm? no\n\x1b[?25h\nCancelled\n")
            sys.stdout.flush()
            sys.exit(0)

    if to_delete_merged_local:
        print("Delete merged local branches:", flush=True)
        for item in sorted(to_delete_merged_local, key=lambda x: x["short"]):
            if item.get("non_tracking"):
                print(f"  - {item['short']} (non-tracking)", flush=True)
            else:
                print(f"  - {item['short']}", flush=True)

    if to_delete_merged_remote:
        print("Delete merged remote refs:", flush=True)
        for item in sorted(to_delete_merged_remote, key=lambda x: x["short"]):
            remote=item["remote"]
            refname=item["refname"]
            if item.get("non_upstream"):
                print(f"  - {remote}, {refname} (non-upstream)", flush=True)
            else:
                print(f"  - {remote}, {refname}", flush=True)

    if to_delete_stray:
        print("Delete stray local branches:", flush=True)
        for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
            print(f"  - {lb['short']}", flush=True)

    if to_delete_diverged_remote:
        print("Delete diverged remote refs:", flush=True)
        for item in sorted(to_delete_diverged_remote, key=lambda x: x["short"]):
            print(f"  - {item['remote']}, {item['refname']}", flush=True)

    if head_to_delete:
        # find subject
        info = None
        for lb in local_branches:
            if lb["short"]==head_to_delete:
                info=lb
                break
        obj_short = info["obj"][:7] if info else ""
        subject = info.get("subject","") if info else ""
        if dry_run:
            print(f"Note: switching to 'refs/heads/{head_to_delete}' (dry run)", flush=True)
            print("You are in 'detached HED' state... blah blah...", flush=True)
            print(f"HEAD is now at {obj_short} {subject} (dry run)", flush=True)
        else:
            print(f"Note: switching to 'refs/heads/{head_to_delete}'.", flush=True)
            subprocess.run(["git","checkout", f"refs/heads/{head_to_delete}"], stdout=sys.stdout, stderr=sys.stderr)

    all_remote = to_delete_merged_remote + to_delete_diverged_remote
    for item in sorted(all_remote, key=lambda x: x["short"]):
        remote=item["remote"]
        refname=item["refname"]
        if dry_run:
            subprocess.run(["git","push","--delete","--no-verify","--dry-run", remote, refname], stdout=sys.stdout, stderr=sys.stderr)
        else:
            subprocess.run(["git","push","--delete","--no-verify", remote, refname], stdout=sys.stdout, stderr=sys.stderr)

    for item in sorted(to_delete_merged_local, key=lambda x: x["short"]):
        short=item["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).", flush=True)
        else:
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

    for lb in sorted(to_delete_stray, key=lambda x: x["short"]):
        short=lb["short"]
        if dry_run:
            print(f"Delete branch {short} (dry run).", flush=True)
        else:
            subprocess.run(["git","branch","--delete","--force", short], stdout=sys.stdout, stderr=sys.stderr)

if __name__=="__main__":
    main()
