                is_prot = is_protected(short, protected_patterns) if protected_patterns else None
                if is_prot:
                    remaining_remote.append((short, f"[merged non-upstream, but: protected by a pattern `{is_prot}`]", None))
                else:
                    to_delete_merged_remote.append({"remote":remote_name,"refname":f"refs/heads/{short[len(remote_name)+1:]}","short":short,"obj":rb["obj"],"non_upstream":True})
            else:
                if not remote_enabled:
                    msg=f"Make it upstream of a tracking branch or add `--delete 'remote:{remote_name}'` flag."
